package com.kennedy.wallet.controller;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;import org.springframework.web.context.request.WebRequest;import com.kennedy.wallet.service.TransferService;
@RestControllerAdvice public class ApiExceptionHandler extends ResponseEntityExceptionHandler {
 @ExceptionHandler(TransferService.IdempotencyConflictException.class) ResponseEntity<ProblemDetail> idempotencyConflict(TransferService.IdempotencyConflictException ex){ProblemDetail p=ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY,"Idempotency key was used with a different request");p.setTitle("Idempotency conflict");p.setProperty("code","IDEMPOTENCY_KEY_REUSED");return ResponseEntity.unprocessableEntity().body(p);}
 @ExceptionHandler(TransferService.RecipientUnavailableException.class) ResponseEntity<ProblemDetail> recipientUnavailable(TransferService.RecipientUnavailableException ex){ProblemDetail p=ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,"Recipient is unavailable");p.setTitle("Recipient unavailable");p.setProperty("code","RECIPIENT_UNAVAILABLE");return ResponseEntity.status(HttpStatus.NOT_FOUND).body(p);}
 @ExceptionHandler(TransferService.FraudBlockedException.class) ResponseEntity<ProblemDetail> fraudBlocked(TransferService.FraudBlockedException ex){ProblemDetail p=ProblemDetail.forStatusAndDetail(HttpStatus.FORBIDDEN,"Transfer was blocked by risk controls");p.setTitle("Transfer blocked");p.setProperty("code","FRAUD_BLOCKED");return ResponseEntity.status(HttpStatus.FORBIDDEN).body(p);}
 @ExceptionHandler(org.springframework.web.server.ResponseStatusException.class) ResponseEntity<ProblemDetail> responseStatus(org.springframework.web.server.ResponseStatusException ex){HttpStatusCode status=ex.getStatusCode();ProblemDetail p=ProblemDetail.forStatusAndDetail(status,"Request could not be completed");p.setTitle("Request rejected");p.setProperty("code","REQUEST_REJECTED");return ResponseEntity.status(status).body(p);}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ProblemDetail> badRequest(IllegalArgumentException ex){ProblemDetail p=ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,ex.getMessage());p.setTitle("Request rejected");p.setProperty("code","REQUEST_REJECTED");return ResponseEntity.badRequest().body(p);}
 @ExceptionHandler(Exception.class) ResponseEntity<ProblemDetail> internal(Exception ex){ProblemDetail p=ProblemDetail.forStatusAndDetail(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred");p.setTitle("Internal error");p.setProperty("code","INTERNAL_ERROR");return ResponseEntity.internalServerError().body(p);}
}
